"""Accounts generated by the native IKEv2 installer on this guest."""
import contextlib
import fcntl
import os
from pathlib import Path
import re
import secrets
import socket
import tempfile

import vici
from vici.exception import CommandException, SessionException

GATEWAY_ERRORS = (OSError, CommandException, SessionException)

CONFIG = Path('/etc/swanctl/conf.d/apple-users.conf')
HOST = Path('/etc/apple-ikev2/hostname')
LOCK = Path('/run/lock/apple-vpn-accounts.lock')
NAME = re.compile(r'[A-Za-z0-9_-]{1,64}')
BLOCK = re.compile(r'\s*(eap-[\w-]+)\s*\{\s*id\s*=\s*([\w-]+)\s+secret\s*=\s*"([^"\\\r\n]+)"\s*\}', re.ASCII)


def load():
    text = CONFIG.read_text()
    outer = re.fullmatch(r'\s*secrets\s*\{(.*)\}\s*', text, re.S)
    if not outer:
        raise ValueError("Unrecognized native credential file. Review apple-users.conf.")
    body = outer[1].strip()
    accounts = {}
    sections = set()
    while body:
        match = BLOCK.match(body)
        if not match or match[2] in accounts or match[1] in sections:
            raise ValueError("Custom credential syntax found. Review apple-users.conf before editing here.")
        section, name, password = match.groups()
        accounts[name] = (section, password)
        sections.add(section)
        body = body[match.end():].strip()
    return accounts


def save(accounts):
    with tempfile.NamedTemporaryFile(mode='w', dir=CONFIG.parent, delete=False) as tmp:
        try:
            tmp.write('secrets {\n')
            for name, (section, password) in accounts.items():
                tmp.write(f'  {section} {{\n    id = {name}\n    secret = "{password}"\n  }}\n')
            tmp.write('}\n')
            tmp.flush()
            os.fsync(tmp.fileno())
            os.replace(tmp.name, CONFIG)
        finally:
            Path(tmp.name).unlink(missing_ok=True)


@contextlib.contextmanager
def gateway():
    try:
        with socket.socket(socket.AF_UNIX) as sock:
            sock.settimeout(5)
            sock.connect('/run/charon.vici')
            yield vici.Session(sock)
    except GATEWAY_ERRORS as exc:
        raise RuntimeError("Gateway communication failed. Check strongswan.service and refresh.") from exc


def sessions(client):
    for entry in client.list_sas({'ike': 'apple'}):
        for sa in entry.values():
            # charon omits remote-eap-id when it equals the IKE identity.
            owner = sa.get('remote-eap-id', sa.get('remote-id'))
            if sa.get('state') == b'ESTABLISHED' and owner:
                yield owner.decode(errors='replace'), sa


def listing():
    if not CONFIG.exists():
        return dict(installed=False, users=[])
    users = {name: dict(name=name, sessions=0, upload=0, download=0) for name in load()}
    online = True
    try:
        with gateway() as client:
            for name, sa in sessions(client):
                if name in users:
                    row = users[name]
                    row['sessions'] += 1
                    for child in sa.get('child-sas', {}).values():
                        row['upload'] += int(child.get('bytes-in', 0))
                        row['download'] += int(child.get('bytes-out', 0))
    except RuntimeError:
        online = False
    return dict(installed=True, online=online, hostname=HOST.read_text().strip(), users=list(users.values()))


def change(name, remove=False):
    if not isinstance(name, str) or not NAME.fullmatch(name):
        raise ValueError("Use 1–64 letters, digits, dashes or underscores.")
    with LOCK.open('a') as lock, gateway() as client:
        fcntl.flock(lock, fcntl.LOCK_EX)
        accounts = load()
        old = accounts.copy()
        if remove:
            if name not in accounts:
                raise ValueError("Account already removed.")
            section, password = accounts.pop(name)
        else:
            if name in accounts:
                raise ValueError("Username already exists.")
            section, password = 'eap-web-' + secrets.token_hex(12), secrets.token_hex(18)
            accounts[name] = section, password
        save(accounts)
        try:
            if remove:
                client.unload_shared({'id': section})
            else:
                client.load_shared({'id': section, 'type': 'EAP', 'owners': [name], 'data': password})
        except Exception:
            save(old)
            raise
        if remove:
            try:
                active = [sa['uniqueid'] for owner, sa in sessions(client) if owner == name]
                for session_id in active:
                    list(client.terminate({'ike-id': session_id, 'timeout': '2000', 'force': 'yes'}))
            except GATEWAY_ERRORS as exc:
                raise RuntimeError("Credential revoked. Check active sessions with swanctl --list-sas.") from exc
        return {'name': name} if remove else {'name': name, 'password': password}
